import{Kb as t,Ya as m,sb as e,tb as i,ub as n}from"./chunk-AQTDFIZG.mjs";import"./chunk-L566CONE.mjs";var c=(()=>{let o=class o{};o.\u0275fac=function(d){return new(d||o)},o.\u0275cmp=m({type:o,selectors:[["nar-manifesto"]],decls:145,vars:0,consts:[[1,"min-h-screen","bg-white","text-ink-900"],[1,"bg-ink-950","text-white"],[1,"container-site","py-20","md:py-28","text-center"],[1,"text-blue-400","text-xs","md:text-sm","font-bold","tracking-[0.3em]","uppercase","mb-5"],[1,"font-display","text-4xl","md:text-6xl","font-bold","leading-tight","max-w-4xl","mx-auto"],[1,"text-white/60","text-base","md:text-lg","mt-6","max-w-2xl","mx-auto","leading-relaxed"],[1,"container-site","pt-12","md:pt-16"],[1,"w-full","overflow-hidden","rounded-xl"],["src","/manifesto-banner.jpg","alt","NOSETHA Africa Reads","loading","eager","fetchpriority","high",1,"w-full","h-auto","object-cover"],[1,"container-site","py-16","md:py-24"],[1,"max-w-4xl","mx-auto"],[1,"mb-16","md:mb-20"],[1,"text-blue-600","text-xs","font-bold","tracking-[0.25em]","uppercase","mb-4"],[1,"font-display","text-3xl","md:text-4xl","font-bold","text-ink-950","mb-8"],[1,"space-y-5","text-slate-600","leading-8","text-base","md:text-lg"],[1,"border-t","border-slate-200","my-14"],[1,"space-y-8"],[1,"text-ink-950","font-bold","text-lg","mb-2"],[1,"text-slate-600","leading-8"],[1,"text-ink-950"],[1,"bg-ink-950","text-white","py-20","md:py-28"],[1,"container-site","max-w-4xl","mx-auto","text-center"],[1,"text-blue-400","text-xs","font-bold","tracking-[0.25em]","uppercase","mb-5"],[1,"font-display","text-3xl","md:text-5xl","font-bold","mb-10"],[1,"space-y-6","text-white/75","text-lg","md:text-xl","leading-9"],[1,"w-16","h-1","bg-blue-500","mx-auto","my-10"],[1,"font-display","text-2xl","md:text-4xl","font-bold","text-white","mb-5"],[1,"text-blue-300","font-semibold","text-lg","md:text-2xl","leading-relaxed"]],template:function(d,r){d&1&&(e(0,"main",0)(1,"section",1)(2,"div",2)(3,"p",3),t(4," NOSETHA AFRICA READS "),i(),e(5,"h1",4),t(6," The NOSETHA Africa Reads Manifesto "),i(),e(7,"p",5),t(8," Africa must read. Africa must think. Africa must recognise and invest in the power of its own mind. "),i()()(),e(9,"section",6)(10,"div",7),n(11,"img",8),i()(),e(12,"section",9)(13,"div",10)(14,"article",11)(15,"p",12),t(16," 01 / Our Foundation "),i(),e(17,"h2",13),t(18," Our Conviction "),i(),e(19,"div",14)(20,"p"),t(21," The future of a continent is determined not merely by the abundance of its natural resources, but also by the quality of thought, judgement and imagination of its people. "),i(),e(22,"p"),t(23," Africa possesses immense human potential. Yet potential, however abundant, cannot fulfil itself without the cultivation of knowledge, the discipline of thought and the opportunity to demonstrate intellectual ability. "),i(),e(24,"p"),t(25," Reading is fundamental to this process. But reading, in its fullest sense, is more than the ability to recognise words on a page. It is the capacity to understand, interpret, question, reason and draw meaning from what one encounters. "),i(),e(26,"p"),t(27," A society that reads without thinking has not yet realised the full promise of reading. A society that thinks without questioning risks surrendering its intellectual independence. "),i(),e(28,"p"),t(29," We read to understand. We think to question. We compete to demonstrate what our minds can achieve. We rise through knowledge, not through the limitations of others. "),i(),e(30,"p"),t(31," It is this conviction that informs NOSETHA AFRICA READS. "),i()()(),n(32,"div",15),e(33,"article",11)(34,"p",12),t(35," 02 / Our Principles "),i(),e(36,"h2",13),t(37," What We Believe "),i(),e(38,"div",16)(39,"div")(40,"h3",17),t(41," We believe in the transformative power of reading. "),i(),e(42,"p",18),t(43," Reading opens minds to ideas, experiences and possibilities beyond the immediate circumstances of one's existence. It expands intellectual horizons and equips individuals to engage more meaningfully with the world. "),i()(),e(44,"div")(45,"h3",17),t(46," We believe knowledge must be accompanied by understanding. "),i(),e(47,"p",18),t(48," The objective is not merely to accumulate information, but to cultivate the capacity to examine it, challenge assumptions, recognise contradictions and arrive at reasoned conclusions. "),i()(),e(49,"div")(50,"h3",17),t(51," We believe intellectual achievement deserves recognition. "),i(),e(52,"p",18),t(53," Intelligence, comprehension, creativity and critical thinking are valuable human capacities. They deserve opportunities for expression, distinction and public recognition. "),i()(),e(54,"div")(55,"h3",17),t(56," We believe competition can serve a higher purpose. "),i(),e(57,"p",18),t(58," When properly structured, competition can stimulate curiosity, sharpen intellectual ability, encourage discipline and inspire people to pursue excellence. It need not diminish others to elevate an individual. "),i()(),e(59,"div")(60,"h3",17),t(61," We believe opportunity should extend beyond privilege. "),i(),e(62,"p",18),t(63," The ability to think, learn and excel is not the exclusive possession of any nation, social class or background. Africa's intellectual potential is widely distributed, even where educational resources and opportunities are not. "),i()(),e(64,"div")(65,"h3",17),t(66," We believe Africa's intellectual future must be continental. "),i(),e(67,"p",18),t(68," The boundaries that separate our countries should not prevent the exchange of ideas, the celebration of intellectual achievement or the development of a shared community of readers and thinkers. "),i()()()(),n(69,"div",15),e(70,"article",11)(71,"p",12),t(72," 03 / Our Vision "),i(),e(73,"h2",13),t(74," What We Seek to Build "),i(),e(75,"div",14)(76,"p"),t(77," NOSETHA AFRICA READS is committed to creating an enduring platform where reading becomes participation, participation finds its expression in our quarterly "),e(78,"strong",19),t(79,"BATTLE OF MINDS"),i(),t(80,", and intellectual achievement becomes a source of recognition and opportunity. "),i(),e(81,"p"),t(82," We seek to bring together readers, students, educators, intellectuals, institutions, communities and individuals who believe that the development of the mind is indispensable to Africa's advancement. "),i(),e(83,"p"),t(84," We envision a continent where reading is not confined to the classroom, intellectual curiosity is not discouraged, questions are not feared, and the pursuit of knowledge is not regarded as an obligation without reward. "),i(),e(85,"p"),t(86," We want reading to become a culture people embrace, an experience they enjoy and an investment they value. "),i()()(),n(87,"div",15),e(88,"article",11)(89,"p",12),t(90," 04 / Beyond Borders "),i(),e(91,"h2",13),t(92," Our Continental Ambition "),i(),e(93,"div",14)(94,"p"),t(95," We are building beyond the limitations of a single country. "),i(),e(96,"p"),t(97," Our ambition is to create an intellectual community that connects Africans across national boundaries through shared reading, critical engagement and healthy competition. "),i(),e(98,"p"),t(99," We want a young person in Nigeria to engage with the same intellectual challenge as a young person in Ghana, Kenya, South Africa, Rwanda or elsewhere on the continent. "),i(),e(100,"p"),t(101," We want their national identities to remain sources of pride while their intellectual participation becomes a source of continental solidarity. "),i(),e(102,"p"),t(103," We believe Africa can celebrate its diversity without surrendering its common aspirations. "),i()()(),n(104,"div",15),e(105,"article",11)(106,"p",12),t(107," 05 / Our Responsibility "),i(),e(108,"h2",13),t(109," Our Commitment "),i(),e(110,"div",14)(111,"p"),t(112," NOSETHA AFRICA READS is committed to intellectual substance, transparency, fairness and the integrity of its processes. "),i(),e(113,"p"),t(114," We will make the value of our intellectual resources evident, the rules of our competitions accessible, the conditions of participation transparent and the recognition of achievement credible. "),i(),e(115,"p"),t(116," We recognise that trust is not established by declarations. It is earned through consistency between what an institution says and what it does. "),i(),e(117,"p"),t(118," Our ambition is therefore not simply to attract attention, but to deserve it. "),i(),e(119,"p"),t(120," We do not merely gather participants. We engage them, challenge their intellect and nurture the emergence of African thinkers through our quarterly "),e(121,"strong",19),t(122,"BATTLE OF MINDS."),i()(),e(123,"p"),t(124," Our purpose extends beyond celebrating winners. We seek to create an environment in which intellectual achievement can be meaningfully demonstrated, recognised and rewarded. "),i(),e(125,"p"),t(126," The tournament is not an end in itself. It is part of a larger ambition to build something enduring, something whose value will outlive any single competition. "),i()()()()(),e(127,"section",20)(128,"div",21)(129,"p",22),t(130," 06 / Our Declaration "),i(),e(131,"h2",23),t(132," Our Declaration "),i(),e(133,"div",24)(134,"p"),t(135," We are not merely bringing Africans together to read books. "),i(),e(136,"p"),t(137," We are bringing them together to discover what books can make possible. "),i(),e(138,"p"),t(139," We are building a culture that recognises the power of knowledge, the value of independent thought and the possibilities that emerge when intellectual ability is given room to flourish. "),i()(),n(140,"div",25),e(141,"h3",26),t(142," NOSETHA AFRICA READS. "),i(),e(143,"p",27),t(144," Africa must read. Africa must think. Africa must recognise and invest in the power of its own mind. "),i()()()())},encapsulation:2});let a=o;return a})();export{c as ManifestoComponent};
